steps.script:
# The cursor is 15" from the pickup point; the ghost must be held at the 6"
# cap. Recorded as meta so the numbers show up in the scenario output.
var m = tree.root.get_node("Main")
var mc = m.movement_controller
var ghost = m.get_node("BoardRoot/MovementGhostVisual")
var ghost_in = Measurement.px_to_inches((ghost.position - mc.drag_start_pos).length())
var cursor_in = Measurement.px_to_inches((Vector2(120.0, 700.0) - mc.drag_start_pos).length())
m.set_meta("clamp_probe", "cursor=%.2f\" ghost=%.3f\" cap=%.2f\"" % [cursor_in, ghost_in, mc._get_effective_move_cap()])
return cursor_in > 14.0 and abs(ghost_in - 6.0) <= 0.05

# Ghost follows the cursor all 15" out, and the preview says so.
var m = tree.root.get_node("Main")
var mc = m.movement_controller
var ghost = m.get_node("BoardRoot/MovementGhostVisual")
var ghost_in = Measurement.px_to_inches((ghost.position - mc.drag_start_pos).length())
m.set_meta("unclamped_probe", "ghost=%.2f\" path_valid=%s" % [ghost_in, str(mc.path_valid)])
return ghost_in > 14.0 and not mc.path_valid

# Picking a different unit mid-session raises a "Switch Unit?" confirm; after
# a reset it does not. Press it when it is there, no-op when it is not, so the
# step is robust either way.
var stack: Array = [tree.root]
while not stack.is_empty():
	var n = stack.pop_back()
	for c in n.get_children():
		stack.append(c)
	if n is Button and n.visible and not n.disabled and str(n.text).begins_with("Switch to"):
		n.emit_signal("pressed")
		return "pressed: %s" % n.text
return "no switch dialog"

# The clamp costs terrain with the SAME function that validates the drop, so
# the stop it picks is one the phase will accept. Geometrically it is well
# short of the 8" cap (the ruin's climb + difficult-ground cost eats the rest),
# and crucially _compute_move_rejection agrees it is legal.
var m = tree.root.get_node("Main")
var mc = m.movement_controller
var ghost = m.get_node("BoardRoot/MovementGhostVisual")
var ghost_in = Measurement.px_to_inches((ghost.position - mc.drag_start_pos).length())
var cost = mc._move_cost_inches(ghost.position)
m.set_meta("terrain_probe", "ghost=%.3f\" total_cost=%.3f\" cap=%.2f\" reject='%s'" % [ghost_in, cost, mc._get_effective_move_cap(), mc._compute_move_rejection(ghost.position)])
return ghost_in < 8.0 and cost <= mc._get_effective_move_cap() + 0.02 and mc._compute_move_rejection(ghost.position) == ""
